# Surah Al-An'am (chapter 6) — part 4: ayat 34-43 (IDs 823-832)
SURAH = 6

ENTRIES = {
823: (
"اور بے شک — تم سے پہلے کے — بہت سے رسولوں کو جھٹلایا گیا — پس انہوں نے — جو — جھٹلایا گیا — اس پر — صبر کیا — اور ایذارسانی — جھیلی — یہاں تک کہ ان کے پاس ہم نے نصرت بھیج دی — اور اللہ کے کلمات — کوئی بدل نہیں سکتا — اور بے شک آپ کے پاس رسولوں کی خبریں آ چکی ہیں",
"""۱۔ پچھلے رسول بھی جھٹلائے گئے — صبر کیا — نصرت ملی۔
۲۔ ’’وَلَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ فَصَبَرُوا عَلَىٰ مَا كُذِّبُوا وَأُوذُوا حَتَّىٰ أَتَاهُمْ نَصْرُنَا‘‘ — اور بے شک — تم سے پہلے کے — بہت سے رسولوں کو جھٹلایا گیا — پس انہوں نے — جو — جھٹلایا گیا — اس پر — صبر کیا — اور ایذارسانی — جھیلی — یہاں تک کہ ان کے پاس ہم نے نصرت بھیج دی — یعنی رسولوں کا صبر — ان کی فتح کی کنجی تھا۔
۳۔ ’’وَلَا مُبَدِّلَ لِكَلِمَاتِ اللّٰہِ وَلَقَدْ جَاءَكَ مِن نَّبَإِ الْمُرْسَلِينَ‘‘ — اور اللہ کے کلمات — کوئی بدل نہیں سکتا — اور بے شک آپ کے پاس رسولوں کی خبریں آ چکی ہیں — یعنی اللہ کی نصرت کا وعدہ — یقینی ہے۔
۴۔ عملی سبق: حق کی راہ میں مشکلیں جھیلو؛ صبر کرو؛ اللہ کی نصرت حتماً آئے گی۔"""
),
824: (
"اور اگر — ان — کا منہ موڑنا آپ پر بھاری ہو — تو اگر آپ — زمین میں — ایک سوراخ — یا — آسمان میں ایک سیڑھی — پا سکتے ہوں — (پھر بھی) ان کے پاس نشانی — نہیں — آتی — اور اگر اللہ چاہتا تو ان — سب — کو ہدایت پر — جمع کر دیتا — پس آپ — نادانوں — میں سے نہ بنیں",
"""۱۔ کفار کی ضد — اللہ کی مشیت کے بغیر کوئی نشانی کافی نہیں۔
۲۔ ’’وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ اسْتَطَعْتَ أَن تَبْتَغِيَ نَفَقًا فِي الْأَرْضِ أَوْ سُلَّمًا فِي السَّمَاءِ‘‘ — اور اگر — ان — کا منہ موڑنا آپ پر بھاری ہو — تو اگر آپ — زمین میں — ایک سوراخ — یا — آسمان میں ایک سیڑھی — پا سکتے ہوں — یعنی آپ پوری زمین اور آسمان میں بھی نشانی نہیں ڈھونڈ سکتے مگر ان کا دل نہیں بدلے گا۔
۳۔ ’’وَلَوْ شَاءَ اللّٰہُ لَجَمَعَهُمْ عَلَى الْهُدَىٰ فَلَا تَكُونَنَّ مِنَ الْجَاهِلِينَ‘‘ — اور اگر اللہ چاہتا تو ان — سب — کو ہدایت پر — جمع کر دیتا — پس آپ — نادانوں — میں سے نہ بنیں — یعنی ہدایت کا اختیار اللہ کا ہے۔
۴۔ عملی سبق: دوسروں کی ضد سے مایوسی مت کرو؛ ہدایت اللہ کا اختیار ہے۔"""
),
825: (
"بولنے والے — صرف — وہ ہیں جو سنتے ہیں — اور مردے — اللہ — انہیں — اٹھائے گا — پھر وہ اسی کی طرف لوٹائے جائیں گے",
"""۱۔ سننے والے ہی جواب دیتے ہیں۔
۲۔ ’’إِنَّمَا يَسْتَجِيبُ الَّذِينَ يَسْمَعُونَ‘‘ — بولنے والے — صرف — وہ ہیں جو سنتے ہیں — یعنی کان لگا کر سننے والے ہی حق کو قبول کرتے ہیں۔
۳۔ ’’وَالْمَوْتَىٰ يَبْعَثُهُمُ اللّٰہُ ثُمَّ إِلَيْهِ يُرْجَعُونَ‘‘ — اور مردے — اللہ — انہیں — اٹھائے گا — پھر وہ اسی کی طرف لوٹائے جائیں گے — یعنی آخرت میں اللہ کے حضور حاضری — یقینی ہے۔
۴۔ عملی سبق: دل لگا کر قرآن سنو؛ آخرت کی حاضری یاد رکھو۔"""
),
826: (
"اور انہوں نے کہا: اس پر — کوئی نشانی — کیوں — نہیں — اتاری جاتی — اپنے رب کی طرف سے — کہہ دیں: بے شک اللہ ایک نشانی اتارنے پر — قادر ہے — لیکن — ان میں سے اکثر نہیں جانتے",
"""۱۔ کفار کی خواہش — نشانی کی طلب۔
۲۔ ’’وَقَالُوا لَوْلَا نُزِّلَ عَلَيْهِ آيَۃٌ مِّن رَّبِّهِ‘‘ — اور انہوں نے کہا: اس پر — کوئی نشانی — کیوں — نہیں — اتاری جاتی — اپنے رب کی طرف سے — یعنی وہ اپنی مرضی کی نشانی چاہتے تھے۔
۳۔ ’’قُلْ إِنَّ اللّٰہَ قَادِرٌ عَلَىٰ أَن يُنَزِّلَ آيَۃً وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ‘‘ — کہہ دیں: بے شک اللہ ایک نشانی اتارنے پر — قادر ہے — لیکن — ان میں سے اکثر نہیں جانتے — یعنی اللہ قادر ہے — مگر نشانی کے بعد بھی انکار — بے فائدہ ہے۔
۴۔ عملی سبق: نشانیوں کی طلب سے — ایمان مت مانگو — دل کی قبولیت مانگو۔"""
),
827: (
"اور زمین پر چلنے والا — کوئی — جانور — اور ہوا میں — اپنے پر — اڑنے والا — پرندہ — نہیں — مگر — وہ تمہاری جیسی قومیں ہیں — ہم نے — اس — کتاب میں — کوئی چیز نہیں چھوڑی — پھر — وہ — اپنے رب کی طرف جمع کیے جائیں گے",
"""۱۔ ہر جاندار — ایک امت ہے۔
۲۔ ’’وَمَا مِن دَابَّۃٍ فِي الْأَرْضِ وَلَا طَائِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّا أُمَمٌ أَمْثَالُكُمْ‘‘ — اور زمین پر چلنے والا — کوئی — جانور — اور ہوا میں — اپنے پر — اڑنے والا — پرندہ — نہیں — مگر — وہ تمہاری جیسی قومیں ہیں — یعنی ہر جاندار — اللہ کی مخلوق ہے — اپنا اپنا نظام رکھتا ہے۔
۳۔ ’’مَّا فَرَّطْنَا فِي الْكِتَابِ مِن شَيْءٍ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ‘‘ — ہم نے — اس — کتاب میں — کوئی چیز نہیں چھوڑی — پھر — وہ — اپنے رب کی طرف جمع کیے جائیں گے — یعنی قیامت کے دن — سب جاندار — اللہ کے حضور جمع ہوں گے۔
۴۔ عملی سبق: ہر جاندار کا خیال رکھو؛ اللہ کی تخلیق کی قدر کرو۔"""
),
828: (
"اور — جو لوگ — ہماری آیات کو جھٹلاتے ہیں — گونگے اور بہرے — اندھیریوں میں — ہیں — اللہ جسے چاہتا ہے گمراہ کرتا ہے — اور جسے چاہتا ہے سیدھا راستہ پر رکھتا ہے",
"""۱۔ آیات کی تکذیب — اندھیریوں میں — گونگے اور بہرے بنا دیتی ہے۔
۲۔ ’’وَالَّذِينَ كَذَّبُوا بِآيَاتِنَا صُمٌّ وَبُكْمٌ فِي الظُّلُمَاتِ‘‘ — اور — جو لوگ — ہماری آیات کو جھٹلاتے ہیں — گونگے اور بہرے — اندھیریوں میں — ہیں — یعنی حق سے بہرے اور اندھے — کفر کا نتیجہ۔
۳۔ ’’مَن يَشَأِ اللّٰہُ يُضْلِلْهُ وَمَن يَشَأْ يَجْعَلْهُ عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ‘‘ — اللہ جسے چاہتا ہے گمراہ کرتا ہے — اور جسے چاہتا ہے سیدھا راستہ پر رکھتا ہے — یعنی ہدایت و گمراہی — اللہ کی طرف سے — انسان کے عمل کے لحاظ سے۔
۴۔ عملی سبق: آیات کی تکذیب مت کرو؛ سیدھے راستے کی التمس کرو۔"""
),
829: (
"کہہ دیں: کیا تم نے سوچا — اگر تم پر اللہ کا عذاب آئے — یا تم پر قیامت آ جائے — تو کیا تم اللہ کے سوا — کسی اور کو — پکارتے ہو — اگر تم سچے ہو",
"""۱۔ مشکل کے وقت — کون پکارا جاتا ہے؟
۲۔ ’’قُلْ أَرَأَيْتَكُمْ إِنْ أَتَاكُمْ عَذَابُ اللّٰہِ أَوْ أَتَتْكُمُ السَّاعَۃُ أَغَيْرَ اللّٰہِ تَدْعُونَ إِن كُنتُمْ صَادِقِينَ‘‘ — کہہ دیں: کیا تم نے سوچا — اگر تم پر اللہ کا عذاب آئے — یا تم پر قیامت آ جائے — تو کیا تم اللہ کے سوا — کسی اور کو — پکارتے ہو — اگر تم سچے ہو — یعنی تکلیف کے وقت — صرف اللہ ہی سچے مددگار ہیں۔
۳۔ عملی سبق: دکھ اور تکلیف میں — صرف اللہ کو پکارو؛ جاہلیت کے معبودوں سے برات۔"""
),
830: (
"بلکہ — وہی — ہیں — جسے تم پکارتے ہو — تو وہ — لو — جس — کے لیے تم پکار رہے ہو — اگر اللہ — پکارتا ہے — دور کر دے — اور تم — جو — شریک بناتے ہو — بھول جاتے ہو",
"""۱۔ اللہ ہی دعا قبول کرتا ہے۔
۲۔ ’’بَلْ إِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَاءَ وَتَنسَوْنَ مَا تُشْرِكُونَ‘‘ — بلکہ — وہی — ہیں — جسے تم پکارتے ہو — تو وہ — لو — جس — کے لیے تم پکار رہے ہو — اگر اللہ — پکارتا ہے — دور کر دے — اور تم — جو — شریک بناتے ہو — بھول جاتے ہو — یعنی تکلیف کے وقت — سارے شریک بھول جاتے ہیں — صرف اللہ پکارا جاتا ہے۔
۳۔ عملی سبق: ہر حالت میں اللہ کو پکارو؛ شریکوں کو فراموش کرو۔"""
),
831: (
"اور بے شک ہم نے — تم سے پہلے — قوموں کی طرف رسول بھیجے — پھر ہم نے انہیں — تنگی اور تکلیف کی حالت میں — پکڑ لیا — شاید کہ وہ — پکار — اٹھیں",
"""۱۔ پچھلی امتوں کی آزمائش — تضرع کی دعوت۔
۲۔ ’’وَلَقَدْ أَرْسَلْنَا إِلَىٰ أُمَمٍ مِّن قَبْلِكَ فَأَخَذْنَاهُم بِالْبَأْسَاءِ وَالضَّرَّاءِ لَعَلَّهُمْ يَتَضَرَّعُونَ‘‘ — اور بے شک ہم نے — تم سے پہلے — قوموں کی طرف رسول بھیجے — پھر ہم نے انہیں — تنگی اور تکلیف کی حالت میں — پکڑ لیا — شاید کہ وہ — پکار — اٹھیں — یعنی تکلیف — تضرع اور توبہ — کے لیے بھیجی گئی۔
۳۔ عملی سبق: تکلیف کو اللہ کی طرف سے امتحان سمجھو؛ تضرع کرو۔"""
),
832: (
"پس — جب ان کے پاس ہمارا عذاب آیا تو انہوں نے — کیوں نہیں — پکار — اٹھے — لیکن — ان کے دل — سخت ہو گئے — اور شیطان نے ان کے اعمال کو — ان کے لیے — خوبصورت بنا دیا",
"""۱۔ سخت دل — عذاب کے وقت بھی تضرع نہیں۔
۲۔ ’’فَلَوْلَا إِذْ جَاءَهُم بَأْسُنَا تَضَرَّعُوا‘‘ — پس — جب ان کے پاس ہمارا عذاب آیا تو انہوں نے — کیوں نہیں — پکار — اٹھے — یعنی تکلیف کا وقت — توبہ کا موقع تھا — مگر انہوں نے تضرع نہیں کیا۔
۳۔ ’’وَلَٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ الشَّيْطَانُ مَا كَانُوا يَعْمَلُونَ‘‘ — لیکن — ان کے دل — سخت ہو گئے — اور شیطان نے ان کے اعمال کو — ان کے لیے — خوبصورت بنا دیا — یعنی شیطان — برے اعمال کو بھلا دکھاتا ہے — یہی ہلاکت کا سبب تھا۔
۴۔ عملی سبق: دل سخت مت کرو؛ بر وقت توبہ کرو؛ شیطان کی فریب کاری سے بچو۔"""
),
}
